#!/bin/bash
# Package the Roku screensaver and (optionally) sideload it.
#   DASH_URL=http://192.168.4.99:8088/roku.png ./build.sh                 -> build/HouseDashboard-roku.zip
#   DASH_URL=... ROKU=192.168.4.59 ROKU_PASS=yourdevpassword ./build.sh    -> also installs it on the TV
# The TV needs developer mode on: Home x3, Up x2, Right, Left, Right, Left, Right -> Enable installer -> set a password -> restart.
set -e
cd "$(dirname "$0")"
URL=${DASH_URL:-http://housedash.local:8088/roku.png}
IV=${DASH_INTERVAL:-15}
mkdir -p build
cat > source/config.brs <<BRS
' generated by build.sh
function dashImageUrl() as String
    return "$URL"
end function
function dashInterval() as Integer
    return $IV
end function
BRS
rm -f build/HouseDashboard-roku.zip
zip -q -r build/HouseDashboard-roku.zip manifest source components images
echo "built build/HouseDashboard-roku.zip for $URL"
if [ -n "$ROKU" ]; then
  [ -n "$ROKU_PASS" ] || { echo "set ROKU_PASS to the developer password you chose on the TV"; exit 1; }
  curl -s --digest -u "rokudev:$ROKU_PASS" -F "mysubmit=Install" -F "archive=@build/HouseDashboard-roku.zip" "http://$ROKU/plugin_install" | grep -o '<font[^>]*>[^<]*</font>' | sed 's/<[^>]*>//g' || true
  echo "installed on $ROKU - now on the TV: Settings -> Screensaver -> House Dashboard"
fi
